<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $client ? 'Edit' : 'Add' ?> Client — Lex Factum</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"></head><body><div class="crm-wrap"><div class="eyebrow">CRM · Client Portal</div><h1><?= $client ? 'Edit Client' : 'Add Client' ?></h1><?php if (!$client): ?><p class="portal-note">A client portal account will be created automatically. A secure temporary password will be generated and emailed to the client. The password will also be shown to you once after creation.</p><?php endif; ?><form method="post" action="<?= $action ?>"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><div class="form-grid"><label>Name<input name="name" required maxlength="160" value="<?= esc(old('name',$client['name']??'')) ?>"></label><label>Email<input type="email" name="email" <?= $client ? '' : 'required' ?> maxlength="190" value="<?= esc(old('email',$client['email']??'')) ?>"><small><?= $client ? 'Used for the existing portal account.' : 'Required — portal credentials are sent here.' ?></small></label><label>Phone<input name="phone" maxlength="30" value="<?= esc(old('phone',$client['phone']??'')) ?>"></label><label>Alternate Phone<input name="alternate_phone" maxlength="30" value="<?= esc(old('alternate_phone',$client['alternate_phone']??'')) ?>"></label><label>City<input name="city" value="<?= esc(old('city',$client['city']??'')) ?>"></label><label>State<input name="state" value="<?= esc(old('state',$client['state']??'')) ?>"></label><label>Status<select name="status"><option value="active" <?= old('status',$client['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= old('status',$client['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></label><label>Address<textarea name="address"><?= esc(old('address',$client['address']??'')) ?></textarea></label><label>Notes<textarea name="notes"><?= esc(old('notes',$client['notes']??'')) ?></textarea></label></div><button type="submit">Save Client</button> <a href="<?= site_url('admin/crm/clients') ?>">Cancel</a></form></div><style>.crm-wrap{max-width:1000px;margin:110px auto;padding:0 24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:25px 0}.form-grid label{display:flex;flex-direction:column;gap:7px}.form-grid textarea{min-height:110px}.form-grid small{opacity:.6}input,select,textarea{padding:12px;border-radius:9px;border:1px solid #aaa;background:rgba(255,255,255,.06);color:inherit}button{padding:12px 18px;border-radius:9px;border:0;cursor:pointer}.portal-note{padding:15px;border:1px solid rgba(184,155,94,.3);border-radius:10px;background:rgba(184,155,94,.07)}@media(max-width:700px){.form-grid{grid-template-columns:1fr}}</style></body></html>
